async function portalAthlete(c:any){if(!c.session?.itemId)throw new Error('Sign in required');const athlete=await c.prisma.athlete.findFirst({where:{portalUserId:c.session.itemId},select:{id:true,fullName:true,sport:true,league:true}});if(!athlete)throw new Error('Client profile not found');return athlete;}
export const portalQueries={
 async myAthleteSummary(_:unknown,a:any,c:any){const athlete=await portalAthlete(c);const [contracts,deals]=await Promise.all([c.prisma.playingContract.findMany({where:{athleteId:athlete.id},select:{id:true,status:true,startSeason:true,endSeason:true},take:100}),c.prisma.endorsementDeal.findMany({where:{athleteId:athlete.id},select:{id:true,status:true,termStart:true,termEnd:true},take:100})]);return {...athlete,contracts,deals};},
 async myDeliverables(_:unknown,a:any,c:any){const athlete=await portalAthlete(c);return c.prisma.deliverable.findMany({where:{deal:{athleteId:athlete.id}},select:{id:true,kind:true,status:true,dueAt:true,proofLink:true},take:100,orderBy:{dueAt:'asc'}});},
 async myInvoices(_:unknown,a:any,c:any){const athlete=await portalAthlete(c);return c.prisma.commissionInvoice.findMany({where:{athleteId:athlete.id},select:{id:true,number:true,status:true,totalCents:true,paidCents:true,currencyCode:true,dueAt:true},take:100,orderBy:{createdAt:'desc'}});},
};
export const portalMutations={async payCommissionInvoice(_:unknown,a:any,c:any){const athlete=await portalAthlete(c);const invoice=await c.prisma.commissionInvoice.findFirst({where:{id:a.invoiceId,athleteId:athlete.id},select:{id:true,status:true}});if(!invoice)throw new Error('Invoice not found');if(!['sent','partially_paid'].includes(invoice.status))throw new Error('Invoice not payable');throw new Error('Payment provider is not configured');}};
export const portalTypeDefs=`extend type Query { myAthleteSummary:AgencyJSON! myDeliverables:AgencyJSON! myInvoices:AgencyJSON! } extend type Mutation { payCommissionInvoice(invoiceId:ID!,idempotencyKey:String!):AgencyJSON! }`;
